mapper.select:
SELECT e.*, IFNULL(t.buy_amount, 0) AS buy_amount, IFNULL(t.sell_amount, 0) AS sell_amount
FROM obt_daily_equity e
LEFT JOIN ( SELECT task_id, trade_date, SUM(CASE WHEN trade_type = 1 THEN amount ELSE 0 END) AS buy_amount, SUM(CASE WHEN trade_type = 2 THEN amount ELSE 0 END) AS sell_amount FROM obt_trade WHERE task_id = #{taskId} GROUP BY task_id, trade_date ) t ON t.task_id = e.task_id AND t.trade_date = e.trade_date
WHERE e.task_id = #{taskId}
AND e.trade_date >= #{startDate}
AND e.trade_date <= #{endDate}
ORDER BY e.trade_date

SELECT COUNT(*)
FROM obt_daily_equity
WHERE task_id = #{taskId}
